import org.springframework.data.repository.query.Param;

public interface ClaimRepository extends JpaRepository<Claim, Long> {

    /** The sheet's claims, newest first. */
    List<Claim> findBySheetIdOrderByIdDesc(String sheetId);

    /** The sheet's claims as they are listed, newest first. */
    List<Claim> findBySheetIdOrderByListedDescIdDesc(String sheetId);

    /** Give the claim the next place it is listed at: it is listed as the newest. */
    @Modifying(flushAutomatically = true, clearAutomatically = true)
    @Query(value = "update claim set listed = next value for claim_listed_seq where id = :id", nativeQuery = true)
    int relist(@Param("id") Long id);

    /** Give the claim the next place in the order claims are added: it arrives on a sheet as newly added. */
    @Modifying(flushAutomatically = true, clearAutomatically = true)
    @Query(value = "update claim set added_seq = next value for claim_added_seq where id = :id", nativeQuery = true)
    int arrive(@Param("id") Long id);

    /** A person's claims on the sheet, newest first. */
    List<Claim> findBySheetIdAndPersonIdOrderByIdDesc(String sheetId, Long personId);

    /** The claim of a person on the sheet with a number. */
    Optional<Claim> findBySheetIdAndPersonIdAndNumber(String sheetId, Long personId, String number);

    /** The claim on the sheet with a reference key. */
    Optional<Claim> findBySheetIdAndRefKey(String sheetId, String refKey);

    Optional<Claim> findByIdAndSheetId(Long id, String sheetId);

    /** Release every editor's lock on the sheet's claims. */
    @Modifying(flushAutomatically = true, clearAutomatically = true)
    @Query("update Claim c set c.lockedBy = null where c.sheetId = :sheetId and c.lockedBy is not null")
    int unlockAll(@Param("sheetId") String sheetId);
}
package net.officefloor.hq.app.claim;

/**
 * A claim's status: DRAFT when added; a DRAFT claim may be opened, an OPEN one settled, and a DRAFT,
 * OPEN or PENDING one voided. An OPEN claim a clerk settles above the clerk limit goes PENDING, which
 * a steward approves (SETTLED) or rejects (back to OPEN). A steward may void a SETTLED claim within
 * {@link #VOID_SETTLED_DAYS} days of its settlement; VOID is final. A DRAFT claim may be DELETED, and
 * restored to a DRAFT on the sheet's today it was deleted. A DRAFT opened while its due is above the
 * sheet's review threshold goes to REVIEW instead, which a steward reviews (OPEN) and anyone may void.
 * Only OPEN, PENDING and SETTLED claims count.
 */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;

    /** The days after its settlement (by the sheet's today) a SETTLED claim may still be voided. */
    public static final int VOID_SETTLED_DAYS = 7;

    /** Whether a claim may move from this status to {@code next}. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN, REVIEW -> this == DRAFT;
            case SETTLED, PENDING -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
            case DELETED -> this == DRAFT;
            case DRAFT -> this == DELETED;
        };
    }

    /** Whether a claim in this status counts toward what is claimed and due. */
    public boolean counts() {
        return this == OPEN || this == PENDING || this == SETTLED;
    }

    /** Whether a claim in this status is open: OPEN, or PENDING a steward's approval. */
    public boolean isOpen() {
        return this == OPEN || this == PENDING;
    }
}
